package com.bank.kth;

import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the Kth largest transaction amount two ways: heap and QuickSelect.
public class KthLargestFinder {

    private static final Logger log = Logger.getLogger(KthLargestFinder.class.getName());

    // Streaming-friendly: size-K min-heap, root is Kth largest. O(n log K).
    public long byHeap(long[] amounts, int k) {
        PriorityQueue<Long> heap = new PriorityQueue<>(); // min-heap
        for (long a : amounts) {
            heap.offer(a);
            if (heap.size() > k) {
                heap.poll(); // drop the smallest, keep K largest
            }
        }
        long result = heap.peek();
        log.info("Kth largest (heap) k=" + k + " -> " + result);
        return result;
    }

    // In-memory: QuickSelect for index (n-k). Average O(n).
    public long byQuickSelect(long[] a, int k) {
        int target = a.length - k; // index in ascending sorted order
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int p = partition(a, lo, hi);
            if (p == target) {
                log.info("Kth largest (quickselect) k=" + k + " -> " + a[p]);
                return a[p];
            } else if (p < target) {
                lo = p + 1;
            } else {
                hi = p - 1;
            }
        }
        throw new IllegalStateException("unreachable");
    }

    private int partition(long[] a, int lo, int hi) {
        int r = lo + (int) (Math.random() * (hi - lo + 1)); // random pivot
        swap(a, r, hi);
        long pivot = a[hi];
        int i = lo;
        for (int j = lo; j < hi; j++) {
            if (a[j] < pivot) {
                swap(a, i++, j);
            }
        }
        swap(a, i, hi);
        return i;
    }

    private void swap(long[] a, int i, int j) {
        long t = a[i]; a[i] = a[j]; a[j] = t;
    }
}
