package com.bank.kth;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class KthLargestDemo {

    private static final Logger log = Logger.getLogger(KthLargestDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Kth Largest Transaction Amount");
        long[] amounts = {5000, 12000, 800, 25000, 3000, 17500, 9000};
        int k = 3; // 3rd largest

        KthLargestFinder finder = new KthLargestFinder();
        finder.byHeap(amounts.clone(), k);          // heap on a copy
        finder.byQuickSelect(amounts.clone(), k);   // quickselect mutates
    }
}
